// Captured-mail, synthetic replacement flow against actual loopback routers.
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{randomUUID}=require('node:crypto');
const {chromium}=require(process.env.PLAYWRIGHT_MODULE);const origin=process.env.TRANSFER_QA_ORIGIN||'http://127.0.0.1:18915';if(new URL(origin).hostname!=='127.0.0.1')throw Error('Local QA only');const output=path.resolve(process.env.TRANSFER_QA_OUTPUT||'/tmp/transfer-reinvite-live');fs.mkdirSync(output,{recursive:true});
async function api(endpoint,role='seller',body){const r=await fetch(origin+endpoint,{method:body?'POST':'GET',headers:{Authorization:'Bearer qa-web-'+role,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const data=await r.json();assert.equal(r.status,200,JSON.stringify(data));return data;}
(async()=>{const browser=await chromium.launch({channel:'chrome',headless:true}),context=await browser.newContext({viewport:{width:390,height:844},locale:'cs-CZ'});await context.route('**/*',r=>new URL(r.request().url()).origin===origin?r.continue():r.abort());const page=await context.newPage(),checks=[];
try{const car=await api('/api/v1/vehicles','seller',{nickname:'QA nové pozvání '+Date.now(),brand:'Škoda',model:'Pouze syntetický test'});const state=await api(`/api/v1/vehicles/${car.id}/lifecycle`);const sale=await api(`/api/v1/vehicles/${car.id}/lifecycle`,'seller',{client_id:randomUUID(),ownership_id:state.ownership_id,ownership_token:state.ownership_token,expected_version:state.version,action:'sold',sale:{mode:'outside_app',reason:'dealer'}});const archive=sale.archive_id;assert.equal((await api('/api/v1/vehicle-archives/'+archive)).can_invite_new_owner,true);
async function invite(){await page.evaluate(id=>VehicleTransfers.sendFromArchive(id),archive);await page.getByLabel('E-mail nového majitele',{exact:true}).fill('web-buyer@example.com');await page.getByRole('button',{name:'Připravit pozvánku'}).click();await page.locator('.referral-confirm').getByRole('button',{name:'Poslat pozvánku',exact:true}).click();await page.getByRole('heading',{name:'Vámi odeslané pozvánky'}).waitFor();return (await api('/api/v1/vehicle-transfers')).items.find(v=>v.vehicle_id===car.id&&v.status==='pending');}
await page.goto(origin+'/qa/client');await page.waitForSelector('body[data-ready="true"]');const first=await invite();const oldCode=await(await fetch(origin+'/qa/mail-code?buyer_email=web-buyer@example.com')).text();await page.locator(`[data-transfer-id="${first.id}"]`).getByRole('button',{name:'Zrušit pozvánku'}).click();await page.locator('.referral-confirm').getByRole('button',{name:'Zrušit pozvánku',exact:true}).click();await page.waitForFunction(id=>document.querySelector(`[data-transfer-id="${id}"]`)?.textContent.includes('Pozvánka zrušena'),first.id);assert.equal((await api('/api/v1/vehicle-archives/'+archive)).can_invite_new_owner,true);checks.push('Cancellation preserves prior invitation and re-enables old-owner archive invitation');
await page.locator('dialog.referral-dialog').getByRole('button',{name:'Zavřít',exact:true}).click();const replacement=await invite();assert.notEqual(first.id,replacement.id);assert.equal((await api('/api/v1/vehicle-transfers')).items.find(v=>v.id===first.id).status,'cancelled');await page.screenshot({path:path.join(output,'cancelled-and-replacement.png'),fullPage:true});checks.push('Browser creates a distinct replacement; cancelled decision remains visible');
const stale=await fetch(origin+`/api/v1/vehicle-transfers/${first.id}/decision`,{method:'POST',headers:{Authorization:'Bearer qa-web-buyer','Content-Type':'application/json'},body:JSON.stringify({accept:true,code:oldCode})});assert.equal(stale.status,409);await api(`/api/v1/vehicle-transfers/${replacement.id}/decision`,'buyer',{accept:false});assert.equal((await api('/api/v1/vehicle-archives/'+archive)).can_invite_new_owner,true);const third=await api('/api/v1/vehicle-transfers/from-archive/'+archive,'seller',{buyer_email:'web-buyer@example.com'});const code=await(await fetch(origin+'/qa/mail-code?buyer_email=web-buyer@example.com')).text();await api(`/api/v1/vehicle-transfers/${third.id}/decision`,'buyer',{accept:true,code});assert.equal((await api('/api/v1/vehicle-archives/'+archive)).can_invite_new_owner,false);const history=(await api('/api/v1/vehicle-transfers')).items.filter(v=>v.vehicle_id===car.id);assert.deepEqual(history.map(v=>v.status).sort(),['accepted','cancelled','rejected']);checks.push('Old code cannot accept cancelled invite; rejection allows new invite; latest acceptance closes archive invitation');
const result={status:'PASS',date:new Date().toISOString(),origin,vehicle_id:car.id,archive_id:archive,history:history.map(v=>({id:v.id,status:v.status})),checks};fs.writeFileSync(path.join(output,'result.json'),JSON.stringify(result,null,2));console.log(JSON.stringify(result,null,2));}catch(e){await page.screenshot({path:path.join(output,'failure.png'),fullPage:true});fs.writeFileSync(path.join(output,'failure.txt'),e.stack+'\n'+await page.locator('body').innerText());throw e;}finally{await context.close();await browser.close();}})().catch(e=>{console.error(e);process.exitCode=1});
